const { StackRouter } = require('@react-navigation/routers');
const router = StackRouter({});
const opt = { routeNames: ['Tabs', 'Lector', 'Ajustes'], routeParamList: {}, routeGetIdList: {} };
let estado = router.getInitialState(opt);
// una acción entra, un estado nuevo sale (o null si el navegador no la resuelve)
estado = router.getStateForAction(estado, { type: 'NAVIGATE', payload: { name: 'Lector', params: { cap: 1 } } }, opt);
estado = router.getStateForAction(estado, { type: 'PUSH', payload: { name: 'Ajustes' } }, opt);
estado = router.getStateForAction(estado, { type: 'GO_BACK' }, opt);

